class Refusal(RuntimeError): pass

def sha_bytes(b: bytes) -> str: return hashlib.sha256(b).hexdigest()
def sha_file(p: Path) -> str: return sha_bytes(p.read_bytes())
def write_json(p: Path, x: Any) -> None: p.write_text(json.dumps(x, indent=2, sort_keys=True) + "\n", encoding="utf-8")
def read_json(p: Path) -> Any: return json.loads(p.read_text(encoding="utf-8"))

def verify_frozen() -> dict[str, str]:
    actual = {p: sha_file(ROOT / p) for p in FROZEN}
    bad = {p: {"expected": FROZEN[p], "actual": actual[p]} for p in FROZEN if actual[p] != FROZEN[p]}
    if bad: raise Refusal("frozen input digest mismatch: " + json.dumps(bad, sort_keys=True))
    return actual

def rows_and_bindings() -> tuple[list[dict[str, Any]], dict[str, Any]]:
    cohort, bindings = read_json(COMPAT / "cohort-inputs.json"), read_json(COMPAT / "runtime-bindings.json")
    rows = cohort.get("rows")
    if not isinstance(rows, list) or len(rows) != 21 or len({r.get("curve_uid") for r in rows}) != 21:
        raise Refusal("cohort is not exactly 21 unique curve UIDs")
    if sum(r.get("label") == "omitted" for r in rows) != 11 or sum(r.get("label") == "published" for r in rows) != 10:
        raise Refusal("cohort labels are not exactly 11 omitted and 10 published")
    required = {"curve_uid", "curve_id", "label", "n", "p", "ordinal", "seed_hex", "timestamp"}
    if any(set(r) != required for r in rows): raise Refusal("cohort row schema mismatch")
    return rows, bindings

def nested_uid_records(x: Any) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    if isinstance(x, dict):
        ident = x.get("identity")
        if isinstance(ident, dict) and isinstance(ident.get("curve_uid"), str): out.append(x)
        for v in x.values(): out.extend(nested_uid_records(v))
    elif isinstance(x, list):
        for v in x: out.extend(nested_uid_records(v))
    return out

def complete_prior_mapping(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    sources = [read_json(ROOT / "research/nist_seed_skipped_curves_20261016/assessed.json"),
               read_json(ROOT / "research/nist_seed_skipped_curves_20261016/traits.json")]
    provenance = {r["identity"]["curve_uid"]: r for s in sources for r in nested_uid_records(s)}
    corpus = [json.loads(line) for line in (ROOT / "research/nist_seed_selection_20261016/raw/full_prime_order_certificates.jsonl").read_text().splitlines() if line]
    result: dict[str, dict[str, Any]] = {}
    for row in rows:
        uid = row["curve_uid"]; source = provenance.get(uid)
        if source is None: raise Refusal("missing UID in reconstructed provenance: " + uid)
        ident = source["identity"]
        if ident.get("curve_id") != row["curve_id"]: raise Refusal("curve id provenance mismatch: " + uid)
        candidates = [c for c in corpus if c.get("side") == "canonical" and str(c.get("n")) == row["n"]
                      and str(c.get("p")) == row["p"] and c.get("index") == row["ordinal"]
                      and str(c.get("seed", "")).lower() == row["seed_hex"].lower()]
        if len(candidates) != 1: raise Refusal("prior-primality corpus mapping is not unique: " + uid)
        c = candidates[0]
        if not all(c.get(k) is True for k in ("order_certified", "n_prime_pari", "n_times_point_identity", "on_curve")):
            raise Refusal("incomplete prior-primality corpus evidence: " + uid)
        result[uid] = {"corpus_record_sha256": sha_bytes(json.dumps(c, sort_keys=True, separators=(",", ":")).encode()),
                       "source_identity_sha256": sha_bytes(json.dumps(ident, sort_keys=True, separators=(",", ":")).encode()),
                       "canonical_side": c["side"], "order": row["n"]}
    if set(result) != {r["curve_uid"] for r in rows}: raise Refusal("incomplete UID mapping")
    return result

def verify_supervisor_manifest(p: Path, index: int, output: Path, frozen: dict[str, str]) -> dict[str, Any]:
    if not p.is_file(): raise Refusal("exact input-binding manifest is absent")
    m = read_json(p)
    if m.get("schema") != "crypto.autoresearch.nistseed_ecpp_trial_binding.v1": raise Refusal("unknown binding manifest schema")
    if m.get("cohort_index") != index or Path(m.get("output_directory", "")).resolve() != output.resolve():
        raise Refusal("binding manifest index/output mismatch")
    if m.get("frozen_input_sha256") != frozen: raise Refusal("binding manifest frozen digests mismatch")
    if m.get("limits") != LIMITS: raise Refusal("binding manifest limits mismatch")
    if m.get("primary_configuration") != {"serial": True, "full_original_data": True, "proving": True, "n_minus_1": True, "n_plus_1": True, "distributed": False, "debug": False, "fresh_vm": True, "fresh_process_rng": "original ModInitialize: srandom(1)"}:
        raise Refusal("binding manifest changes primary configuration")
    return m

def extract_trace(serial: bytes, original_data: dict[str, str]) -> dict[str, Any]:
    text = serial.replace(b"\r\n", b"\n").decode("utf-8", "replace")
    pats = {"recursive_N": r"^% N_(\\d+)=(\\d+)$", "D": r"^% next D is (-?\\d+)$",
            "factor_list": r"^% (?:factors?|factor list)[:=] ?(.*)$", "route": r"^% (?:route|method)[:=] ?(.*)$",
            "retry": r"^% (?:retry|try)[:=] ?(.*)$", "phase": r"^% (?:phase|step)[:=] ?(.*)$"}
    events = []
    for kind, pat in pats.items():
        for match in re.finditer(pat, text, re.M):
            value: Any = list(match.groups()) if len(match.groups()) > 1 else match.group(1)
            event = {"kind": kind, "printed": True, "value": value}
            if kind == "D": event["catalog_positions"] = [i for i, name in enumerate(sorted(original_data)) if str(original_data[name]) == str(value)]
            events.append(event)
    return {"schema": "trace_schema.json", "raw_serial_sha256": sha_bytes(serial), "events": events,
            "unprinted_state": "UNOBSERVED", "inference_prohibited": "unprinted branches are not reconstructed as attempted"}

def classify(observation: dict[str, Any]) -> str:
    prover, checker = observation.get("prover"), observation.get("checker")
    if not isinstance(prover, dict) or not prover.get("vm_valid") or prover.get("child_exit") != 0: return "INDETERMINATE"
    if observation.get("certificate_admitted") is not True or not isinstance(checker, dict) or not checker.get("vm_valid") or checker.get("child_exit") != 0: return "INDETERMINATE"
    return "PRIOR_PRIMALITY_EVIDENCE_REQUIRED"

def install_per_trial_cache(output: Path) -> None:
    """Redirect qemu_controls' formerly shared image path to this trial only."""
    import qemu_controls
    view = output / "runtime-cache"
    view.mkdir()
    source_kernel = qemu_controls.RUNTIME / "vmlinuz-lts"
    (view / "vmlinuz-lts").symlink_to(source_kernel)
    (view / "images").mkdir()
    qemu_controls.RUNTIME = view

def run(index: int, output: Path, binding_manifest: Path) -> dict[str, Any]:
    if type(index) is not int or not 0 <= index <= 20: raise Refusal("cohort index must be an integer in [0,20]")
    if output.exists(): raise Refusal("duplicate output directory refused")
    frozen = verify_frozen(); rows, bindings = rows_and_bindings(); manifest = verify_supervisor_manifest(binding_manifest, index, output, frozen)
    prior = complete_prior_mapping(rows); row = rows[index]
    output.parent.mkdir(parents=True, exist_ok=True); output.mkdir(mode=0o700)
    try:
        sys.path.insert(0, str(COMPAT)); import cohort_case
        install_per_trial_cache(output)
        observation = cohort_case.execute_case(index, output)
        serial = (output / "prover" / "serial.raw").read_bytes()
        trace = extract_trace(serial, bindings["original_data"])
        write_json(output / "trace.json", trace)
        observation["prior_primality_evidence"] = prior[row["curve_uid"]]
        observation["mathematical_classification"] = classify(observation)
        observation["contradictory_legacy_label"] = any(x == "composite" for x in observation.get("legacy_labels", []))
        write_json(output / "observation.json", observation)
        raw = {"schema": "crypto.autoresearch.nistseed_ecpp_raw_result.v1", "cohort_index": index, "curve": row,
               "binding_manifest_sha256": sha_file(binding_manifest), "frozen_input_sha256": frozen,
               "runtime_payloads": bindings["artifacts"], "kernel": bindings["kernel"], "original_data": bindings["original_data"],
               "limits": LIMITS, "fresh_process_rng": "original ModInitialize: srandom(1)",
               "raw_artifacts": {str(p.relative_to(output)): sha_file(p) for p in sorted(output.rglob("*")) if p.is_file()},
               "classification": observation["mathematical_classification"], "censoring": observation["mathematical_classification"] == "INDETERMINATE",
               "legacy_labels_observation_only": observation.get("legacy_labels", []), "named_orders_executed": 1}
        write_json(output / "raw-result.json", raw)
        return raw
    except BaseException as exc:
        failure = {"schema": "crypto.autoresearch.nistseed_ecpp_failure.v1", "cohort_index": index, "curve": row,
                   "exception": type(exc).__name__, "message": str(exc), "classification": "INDETERMINATE", "censoring": True,
                   "named_orders_executed": 1}
        write_json(output / "failure.json", failure)
        raise

def main() -> None:
    ap = argparse.ArgumentParser(description="One future supervisor-selected NIST seed ECPP trial")
    ap.add_argument("--index", required=True, type=int); ap.add_argument("--output", required=True, type=Path)
    ap.add_argument("--input-binding-manifest", required=True, type=Path)
    ns = ap.parse_args(); print(json.dumps(run(ns.index, ns.output, ns.input_binding_manifest), sort_keys=True))
if __name__ == "__main__": main()

#!/usr/bin/env python3
"""Independent fail-closed checker for one future cohort trial directory.

The legacy certificate grammar checker is only one bounded component here.  It
is not an independent general primality verifier; prior-primality corpus mapping
is retained separately and legacy labels remain observations only.
"""
from __future__ import annotations
import argparse
import hashlib
import json
import sys
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import cohort_runner as runner
sys.path.insert(0, str(runner.COMPAT))
from certificate_admission import admit, parse
from guest_framing import valid_frame

class CheckFailure(RuntimeError): pass
def sha(p: Path) -> str: return hashlib.sha256(p.read_bytes()).hexdigest()
def load(p: Path) -> Any: return json.loads(p.read_text(encoding="utf-8"))
def fail(msg: str) -> None: raise CheckFailure(msg)

def artifact(raw: dict[str, Any], out: Path, rel: str) -> Path:
    p = out / rel
    expected = raw.get("raw_artifacts", {}).get(rel)
    if not p.is_file() or not isinstance(expected, str) or sha(p) != expected: fail("missing or mutated retained artifact: " + rel)
    return p

def check_trace(trace: dict[str, Any], serial: bytes, catalog: dict[str, str]) -> None:
    if trace.get("unprinted_state") != "UNOBSERVED" or trace.get("inference_prohibited") != "unprinted branches are not reconstructed as attempted": fail("trace asserts an unprinted branch")
    independently = runner.extract_trace(serial, catalog)
    if trace != independently: fail("trace is not an independent exact extraction")
    for event in trace["events"]:
        if event["kind"] == "D" and any(not isinstance(x, int) or x < 0 or x >= len(catalog) for x in event.get("catalog_positions", [])): fail("D mapping is outside original catalog positions")

def check(output: Path) -> dict[str, Any]:
    raw_path = output / "raw-result.json"
    if not raw_path.is_file(): fail("raw-result.json absent")
    raw = load(raw_path)
    if raw.get("schema") != "crypto.autoresearch.nistseed_ecpp_raw_result.v1": fail("raw schema")
    if raw.get("named_orders_executed") != 1: fail("trial raw record must describe exactly one selected order")
    frozen = runner.verify_frozen()
    if raw.get("frozen_input_sha256") != frozen: fail("frozen binding mismatch")
    rows, bindings = runner.rows_and_bindings(); index = raw.get("cohort_index")
    if type(index) is not int or not 0 <= index < 21 or raw.get("curve") != rows[index]: fail("exact cohort row identity mismatch")
    if raw.get("limits") != runner.LIMITS or raw.get("runtime_payloads") != bindings["artifacts"] or raw.get("kernel") != bindings["kernel"] or raw.get("original_data") != bindings["original_data"]: fail("runtime/data binding mismatch")
    prior = runner.complete_prior_mapping(rows)
    observation_path = artifact(raw, output, "observation.json")
    prover_serial = artifact(raw, output, "prover/serial.raw")
    artifact(raw, output, "prover/qemu.stderr"); artifact(raw, output, "prover/result.json"); artifact(raw, output, "prover/started.json")
    trace_path = artifact(raw, output, "trace.json")
    observation, trace = load(observation_path), load(trace_path)
    if observation.get("curve_uid") != rows[index]["curve_uid"] or observation.get("prior_primality_evidence") != prior[rows[index]["curve_uid"]]: fail("complete prior-primality mapping missing or wrong")
    prover = observation.get("prover")
    if not isinstance(prover, dict): fail("prover status absent")
    serial = prover_serial.read_bytes()
    if prover.get("vm_valid") is not valid_frame(prover.get("qemu_exit"), serial, prover.get("reason")): fail("prover framing/status inconsistency")
    check_trace(trace, serial, bindings["original_data"])
    classification = raw.get("classification")
    if classification not in ("INDETERMINATE", "PRIOR_PRIMALITY_EVIDENCE_REQUIRED"): fail("invalid classification")
    admitted = observation.get("certificate_admitted") is True
    if admitted:
        cert = artifact(raw, output, "prover/certificate.cformat").read_bytes()
        checker_serial = artifact(raw, output, "checker/serial.raw")
        artifact(raw, output, "checker/qemu.stderr"); artifact(raw, output, "checker/result.json"); artifact(raw, output, "checker/started.json")
        checker = observation.get("checker")
        if not isinstance(checker, dict) or checker.get("vm_valid") is not valid_frame(checker.get("qemu_exit"), checker_serial.read_bytes(), checker.get("reason")): fail("checker framing/status inconsistency")
        try: steps = parse(cert, int(rows[index]["n"]))
        except (ValueError, UnicodeError) as e: fail("incomplete/root-mutated certificate: " + str(e))
        stdout = (output / "checker" / "program.stdout").read_bytes()
        if not admit(checker, stdout, cert, int(rows[index]["n"])): fail("legacy checker did not accept complete certificate")
        if observation.get("certificate_steps") != steps or observation.get("certificate_sha256") != hashlib.sha256(cert).hexdigest(): fail("certificate step/digest mismatch")
        if classification != "PRIOR_PRIMALITY_EVIDENCE_REQUIRED" or raw.get("censoring") is not False: fail("admitted classification mismatch")
    else:
        if classification != "INDETERMINATE" or raw.get("censoring") is not True: fail("censoring required for non-admission")
    if set(raw.get("raw_artifacts", {})) != {str(p.relative_to(output)) for p in output.rglob("*") if p.is_file() and p.name != "raw-result.json"}: fail("raw artifact inventory incomplete")
    return {"schema": "crypto.autoresearch.nistseed_ecpp_check.v1", "accepted": True, "cohort_index": index,
            "curve_uid": rows[index]["curve_uid"], "classification": classification,
            "legacy_certificate_component": "bounded grammar/root/step and legacy-checker acceptance only; not a general primality verifier"}

def aa_compare(left: dict[str, Any], right: dict[str, Any]) -> dict[str, Any]:
    """Future non-cohort engineering control; not an extra cohort order/curve."""
    fields = ("classification", "legacy_labels_observation_only", "limits", "runtime_payloads", "kernel", "original_data")
    if any(left.get(k) != right.get(k) for k in fields): fail("A/A semantic mismatch")
    if left.get("curve", {}).get("curve_uid") != right.get("curve", {}).get("curve_uid"): fail("A/A fixture identity mismatch")
    return {"mode": "A/A", "equal": True, "scope": "non-cohort engineering reproducibility control only; not an independent curve or cohort order"}

def main() -> None:
    ap = argparse.ArgumentParser(); ap.add_argument("--output", type=Path, required=True); ns = ap.parse_args()
    print(json.dumps(check(ns.output), sort_keys=True))
if __name__ == "__main__": main()

